def transform(grid):
    out = [row[:] for row in grid]
    points = {}
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value in (1, 2):
                points[value] = (r, c)
    r, c = points[2]
    tr, tc = points[1]
    dr, dc = tr - r, tc - c
    sr = (dr > 0) - (dr < 0)
    sc = (dc > 0) - (dc < 0)
    nr, nc = abs(dr), abs(dc)
    # Begin with one diagonal step, then take the unmatched straight segment,
    # and finish the remaining diagonal steps toward marker 1.
    if nr and nc:
        r += sr
        c += sc
        out[r][c] = 3
    if nr > nc:
        for _ in range(nr - nc):
            r += sr
            out[r][c] = 3
    elif nc > nr:
        for _ in range(nc - nr):
            c += sc
            out[r][c] = 3
    while (r + sr, c + sc) != (tr, tc):
        r += sr
        c += sc
        out[r][c] = 3
    return out
